"""Heat diffusion on the GPU.

Usage: uv run main.py <grid-file>

The grid file holds "<width> <height> <steps>" followed by height rows of
width whole numbers. Each step replaces every cell with
(4 * self + left + right + up + down) // 8, computed by a compute shader.
Out-of-grid neighbours read the nearest cell inside the grid.
"""

import sys

import numpy as np
import wgpu

WORKGROUP = 16

SHADER = """
struct Dims {
    w: u32,
    h: u32,
    pad0: u32,
    pad1: u32,
};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

fn cell(x: u32, y: u32) -> u32 {
    return src[y * dims.w + x];
}

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= dims.w || y >= dims.h) {
        return;
    }
    let left = select(x, x - 1u, x > 0u);
    let right = select(x, x + 1u, x + 1u < dims.w);
    let up = select(y, y - 1u, y > 0u);
    let down = select(y, y + 1u, y + 1u < dims.h);
    let total = 4u * cell(x, y) + cell(left, y) + cell(right, y)
        + cell(x, up) + cell(x, down);
    dst[y * dims.w + x] = total / 8u;
}
"""


def read_grid(path):
    with open(path) as f:
        tokens = f.read().split()
    width, height, steps = (int(t) for t in tokens[:3])
    values = np.array(
        [int(t) for t in tokens[3 : 3 + width * height]], dtype=np.uint32
    )
    return values.reshape(height, width), steps


def diffuse(grid, steps):
    """Run `steps` diffusion steps on the GPU and return the resulting grid."""
    height, width = grid.shape
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    size = grid.nbytes
    buffers = [
        device.create_buffer_with_data(
            data=grid.tobytes(),
            usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
        ),
        device.create_buffer(
            size=size,
            usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
        ),
    ]
    dims = device.create_buffer_with_data(
        data=np.array([width, height, 0, 0], dtype=np.uint32).tobytes(),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": module, "entry_point": "main"},
    )
    layout = pipeline.get_bind_group_layout(0)

    # Ping-pong: step i reads buffers[i % 2] and writes buffers[(i + 1) % 2].
    bind_groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": dims, "offset": 0, "size": dims.size}},
                {"binding": 1, "resource": {"buffer": buffers[i], "offset": 0, "size": size}},
                {"binding": 2, "resource": {"buffer": buffers[1 - i], "offset": 0, "size": size}},
            ],
        )
        for i in range(2)
    ]

    encoder = device.create_command_encoder()
    for step in range(steps):
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, bind_groups[step % 2])
        compute.dispatch_workgroups(
            -(-width // WORKGROUP), -(-height // WORKGROUP), 1
        )
        compute.end()

    final = buffers[steps % 2]
    staging = device.create_buffer(
        size=size,
        usage=wgpu.BufferUsage.COPY_DST | wgpu.BufferUsage.MAP_READ,
    )
    encoder.copy_buffer_to_buffer(final, 0, staging, 0, size)
    device.queue.submit([encoder.finish()])

    staging.map_sync(wgpu.MapMode.READ)
    result = np.frombuffer(staging.read_mapped(), dtype=np.uint32).reshape(
        height, width
    ).copy()
    staging.unmap()
    return result


def main():
    if len(sys.argv) != 2:
        sys.stderr.write("usage: main.py <grid-file>\n")
        return 2

    grid, steps = read_grid(sys.argv[1])
    if steps > 0:
        grid = diffuse(grid, steps)

    out = [" ".join(map(str, row)) for row in grid.tolist()]
    total = int(grid.astype(np.uint64).sum())
    out.append(f"SUM {total}")
    sys.stdout.write("\n".join(out) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())

